"""The UREI 1176LN (config/circuits/urei_1176.yaml, GENERATED by scripts/make_urei_1176.py;
DEVICE_BUILDER_PLAN.md B12): the generated file is current, the pre-flight checks, the idle
point, the manual's gain and response, the maximum output, THD while limiting, the ratio
switch's order and thresholds, the release's range.

Renders run the draft with Newton at 1e-5 (the app's `panel::Device::newton` for this
device: the draft's 1e-3 reads ten times the THD at 10 dB of gain reduction). The factory
trims are the circuit file's (scripts/urei_1176_trim.py). The profile with every figure:
`varimu unit --circuit urei_1176` (varimu.measure.limiter_suite)."""

import dataclasses
import subprocess
import sys

import numpy as np
import pytest

from varimu.circuit import builder
from varimu.circuit.spec import load_circuit, resolve
from varimu.config import CONFIG_DIR, REPO_ROOT

CIRCUIT = CONFIG_DIR / "circuits" / "urei_1176.yaml"
FS = 96000.0
DBU_PEAK_V = 0.775 * np.sqrt(2)
OPEN = {"input_atten_db": 0.0, "output": 1.0, "attack_off": 1}
LIMIT = {"input_atten_db": 0.0, "output": 0.45, "attack": 0.5, "release": 0.0}


def _spec():
    return load_circuit(CIRCUIT)


def _render(x: np.ndarray, probes=("out",), **controls) -> dict[str, np.ndarray]:
    pytest.importorskip("circuitsim", reason="needs `uv sync --extra fast`")
    from varimu.sim import fast, io

    spec = _spec()
    q = dict(resolve(spec))
    q.update(controls)
    st = io.TransientSettings.from_sim_settings(engine="circuitsim", quality="draft")
    st = dataclasses.replace(st, newton_reltol=1e-5, newton_vntol=1e-5)
    r = fast.run_transient(builder.build(spec, q).ir, x, settings=st)
    return {p: np.asarray(r.vectors[f"v({p})"]) for p in probes}


def _tone(dbu: float, seconds: float, f_hz: float = 1000.0) -> np.ndarray:
    t = np.arange(int(FS * seconds)) / FS
    return DBU_PEAK_V * 10 ** (dbu / 20) * np.sin(2 * np.pi * f_hz * t) * np.clip(t / 0.02, 0, 1)


def _level(y: np.ndarray, f_hz: float = 1000.0, frac: float = 0.5) -> float:
    y = y[int(frac * len(y)) :]
    y = y[len(y) - int(int(len(y) * f_hz / FS) * FS / f_hz) :]
    t = np.arange(len(y)) / FS
    return float(20 * np.log10(2 * abs(np.mean(y * np.exp(-2j * np.pi * f_hz * t))) / DBU_PEAK_V))


def _thd(y: np.ndarray, f_hz: float = 1000.0, frac: float = 0.6) -> float:
    y = y[int(frac * len(y)) :]
    t = np.arange(len(y)) / FS
    w = np.hanning(len(y))
    h = [abs(np.sum(w * y * np.exp(-2j * np.pi * k * f_hz * t))) for k in range(1, 11)]
    return float(np.sqrt(sum(x * x for x in h[1:])) / h[0])


def test_generated_file_is_current():
    r = subprocess.run(
        [sys.executable, str(REPO_ROOT / "scripts" / "make_urei_1176.py"), "--check"],
        capture_output=True,
        text=True,
    )
    assert r.returncode == 0, r.stdout + r.stderr


def test_passes_the_preflight_checks_at_the_panel_defaults():
    from varimu import preflight

    ir = builder.build_ir(_spec(), resolve(_spec()))
    assert preflight.check_ir(ir) == []


def test_idle_point():
    """Q6's class-A current through T2's collector winding (80 ohm), the preamp's output
    stage, and Q1's gate held below its pinch-off (2N5457@2's VTO) at the factory Q bias:
    the side chain, not a standing bias, starts the gain reduction."""
    from varimu.devices.library import load_device

    vto = load_device("2N5457@2").vto_v
    r = _render(np.zeros(int(0.2 * FS)), probes=("c6", "po", "gr"), **OPEN)
    i_q6_ma = (30.0 - r["c6"][-1]) / 80.0 * 1e3
    assert 20.0 < i_q6_ma < 35.0, i_q6_ma
    assert 3.0 < r["po"][-1] < 8.0, r["po"][-1]
    assert r["gr"][-1] < vto - 0.1, (r["gr"][-1], vto)


def test_gain_and_response():
    """The manual's 45 dB +-1 and +-1 dB from 20 Hz to 20 kHz (INPUT and OUTPUT fully CW,
    gain reduction off, -50 dBu in)."""
    g = {f: _level(_render(_tone(-50.0, max(0.4, 12 / f), f), **OPEN)["out"], f) + 50.0
         for f in (20.0, 1000.0, 20000.0)}  # fmt: skip
    assert g[1000.0] == pytest.approx(45.0, abs=1.0)
    assert abs(g[20.0] - g[1000.0]) <= 1.0, g
    assert abs(g[20000.0] - g[1000.0]) <= 1.0, g


def test_maximum_output():
    """+22 dBm into 600 ohm at no more than 0.5 % THD (1 kHz, gain reduction off)."""
    y = _render(_tone(22.0 - 45.0, 0.3), **OPEN)["out"]
    assert _level(y) == pytest.approx(22.0, abs=1.0)
    assert _thd(y) < 0.005


def test_thd_while_limiting():
    """Under 0.5 % at 1 kHz with ~10 dB of gain reduction (4:1, RELEASE slowest, the
    manual's condition): the LN circuit's null (R86)."""
    g0 = _level(_render(_tone(-70.0, 0.3), ratio=4, **LIMIT)["out"]) + 70.0
    lvl = -9.0  # ~10 dB of gain reduction at 4:1 (the profile: -8.9 dBu)
    y = _render(_tone(lvl, 1.0), ratio=4, **LIMIT)["out"]
    gr = g0 - (_level(y, frac=0.6) - lvl)
    assert 5.0 < gr < 15.0, gr
    assert _thd(y) < 0.005


def test_ratio_switch_order():
    """The slope above threshold steepens 4 < 8 < 12 < 20 (the ratio switch's order).

    Known misses (DEVICE_CANDIDATES.md, B12's status): the ratios run above the legend
    (the production profile: 6.7 / 10.1 / 12.4 / 27 between 6 and 15 dB of gain reduction,
    on Q1's 2N5457@2), and the higher ratios start limiting lower, not higher (4:1 at -18.7
    dBu, 20:1 at -22.9 dBu with INPUT fully CW): the ratio decks', not the FET's."""
    slopes = {}
    for ratio in (4, 8, 12, 20):
        lo, hi = -12.0, 0.0
        o = {lv: _level(_render(_tone(lv, 0.8), ratio=ratio, **LIMIT)["out"], frac=0.7)
             for lv in (lo, hi)}  # fmt: skip
        slopes[ratio] = (hi - lo) / (o[hi] - o[lo])
    assert slopes[4] < slopes[8] < slopes[12] < slopes[20], slopes


def test_release_range():
    """The GR line's recovery after a burst: ~1 / e in about R56 || R57 x C22 (5M || 270k x
    0.22 uF = 56 ms) fully CW, and R56 x C22 (1.1 s) fully CCW: the manual's 50-1100 ms."""
    taus = {}
    for release in (1.0, 0.0):
        n_on, n_off = int(0.3 * FS), int((0.5 if release else 7.0) * FS)
        t = np.arange(n_on + n_off) / FS
        amp = np.where(t < 0.3, DBU_PEAK_V * 10 ** (-6.0 / 20), DBU_PEAK_V * 10 ** (-40.0 / 20))
        x = amp * np.sin(2 * np.pi * 1000 * t) * np.clip(t / 0.02, 0, 1)
        v = _render(x, probes=("gr",), ratio=4, **{**LIMIT, "release": release})["gr"]
        v0, v1 = v[n_on - 10], v[-1]
        k = np.nonzero((v[n_on:] - (v1 + (v0 - v1) / np.e)) * np.sign(v0 - v1) <= 0)[0]
        taus[release] = k[0] / FS
    assert taus[1.0] == pytest.approx(0.056, rel=0.3), taus
    assert taus[0.0] == pytest.approx(1.1, rel=0.3), taus
